UPDATE community_gate_entries SET revision=@Revision,kind=@Kind,name=@Name,unit_id=@UnitId,occupancy_id=@OccupancyId,resident_user_id=@ResidentUserId,expected_at=@ExpectedAt,approval=@Approval,status=@Status,arrived_at=@ArrivedAt,departed_at=@DepartedAt,accepted_at=@AcceptedAt,received_at=@ReceivedAt,user_id=@UserId WHERE workspace_id=@WorkspaceId AND property_id=@PropertyId AND id=@Id AND revision=@Revision-1;
